          const fs = require('fs');
          const corpus = JSON.parse(fs.readFileSync('data/recovery/canonical-ledger/corpus/manifest.json', 'utf8'));
          const index = JSON.parse(fs.readFileSync('data/recovery/canonical-ledger/indexes/manifest.json', 'utf8'));
          const expected = 32108;
          const moduleTotal = index.modules.reduce((n, x) => n + x.totalRecords, 0);
          const stageTotal = index.implementationStages.reduce((n, x) => n + x.totalRecords, 0);
          const failures = [];
          if (corpus.totalRecords !== expected) failures.push(`corpus total ${corpus.totalRecords} != ${expected}`);
          if (index.totalRecords !== expected) failures.push(`index total ${index.totalRecords} != ${expected}`);
          if (moduleTotal !== expected) failures.push(`module total ${moduleTotal} != ${expected}`);
          if (stageTotal !== expected) failures.push(`stage total ${stageTotal} != ${expected}`);
          if (index.totalBatches !== 22) failures.push(`batch total ${index.totalBatches} != 22`);
          if (index.corpusFingerprint !== corpus.corpusFingerprint) failures.push('corpus fingerprint mismatch');
          if (index.verifiedLive !== false) failures.push('verifiedLive must remain false');
          if (index.deleteAllowed !== false) failures.push('deleteAllowed must remain false');
          if (failures.length) throw new Error(failures.join('; '));
          console.log(JSON.stringify({expected, moduleTotal, stageTotal, batches:index.totalBatches, verifiedLive:index.verifiedLive, deleteAllowed:index.deleteAllowed}, null, 2));
